  StatusOr(const T &value)  // NOLINT(runtime/explicit)
      : status_(Status::OK()), has_value_(true) {
    new (&value_) T(value);
  }
  StatusOr(T &&value)  // NOLINT(runtime/explicit)
      : status_(Status::OK()), has_value_(true) {
    new (&value_) T(std::move(value));
  }

