+StatusOr<int> f_ok() { return 5; }
+StatusOr<int> f_err() { return Status::Invalid("bad"); }
+
+int main() {
+  auto a = f_ok();
+  RAY_CHECK(a.ok());
+  RAY_CHECK(*a == 5);
+  RAY_CHECK(a.value() == 5);
+  RAY_CHECK(a.value_or(9) == 5);
+  RAY_CHECK(a.value_or_default() == 5);
+
+  auto b = f_err();
+  RAY_CHECK(!b.ok());
+  RAY_CHECK(b.value_or(9) == 9);
+  RAY_CHECK(b.value_or_default() == 0);
+  RAY_CHECK(b.code() == StatusCode::Invalid);
+
+  // and_then
+  auto c = a.and_then([](int x) -> StatusOr<int> { return x + 1; });
+  RAY_CHECK(c.ok() && *c == 6);
+  auto d = b.and_then([](int x) -> StatusOr<int> { return x + 1; });
+  RAY_CHECK(!d.ok());
+
+  // or_else
+  auto e = b.or_else([](const Status &) -> StatusOr<int> { return 42; });
+  RAY_CHECK(e.ok() && *e == 42);
+
+  // equality
+  StatusOr<int> g = 5;
+  RAY_CHECK(a == g);
+  RAY_CHECK(a != b);
+
+  // swap
+  StatusOr<int> h = 1, i = Status::Invalid("x");
+  swap(h, i);
+  RAY_CHECK(!h.ok() && i.ok() && *i == 1);
+
+  // conversion StatusOr<Derived> -> StatusOr<Base>
+  StatusOr<std::shared_ptr<int>> sp = std::make_shared<int>(3);
+  RAY_CHECK(sp.ok());
