+  // Default constructor. Constructs an object holding a default-constructed
+  // value and an OK status.
+  StatusOr() : status_(Status::OK()), has_value_(true) { new (&value_) T(); }
+
+  // Implicit construction from a `Status`. The status must not be OK: a
+  // `StatusOr` holding a value should be constructed from a value instead.
+  StatusOr(const Status &status)  // NOLINT(runtime/explicit)
+      : status_(status), has_value_(false) {
+    RAY_CHECK(!status_.ok())
+        << "StatusOr cannot be constructed from an OK status without a value.";
+  }
+  StatusOr(Status &&status)  // NOLINT(runtime/explicit)
+      : status_(std::move(status)), has_value_(false) {
+    RAY_CHECK(!status_.ok())
+        << "StatusOr cannot be constructed from an OK status without a value.";
+  }
+
+  // Implicit construction from a value.
+  StatusOr(const T &value)  // NOLINT(runtime/explicit)
+      : status_(Status::OK()), has_value_(true) {
+    new (&value_) T(value);
+  }
+  StatusOr(T &&value)  // NOLINT(runtime/explicit)
+      : status_(Status::OK()), has_value_(true) {
+    new (&value_) T(std::move(value));
+  }
+
+  // Copy construction and assignment.
+  StatusOr(const StatusOr &other) : status_(other.status_), has_value_(other.has_value_) {
+    if (has_value_) {
+      new (&value_) T(other.value_);
+    }
+  }
+  StatusOr &operator=(const StatusOr &other) {
+    if (this == &other) {
+      return *this;
+    }
+    Clear();
+    status_ = other.status_;
+    has_value_ = other.has_value_;
+    if (has_value_) {
+      new (&value_) T(other.value_);
+    }
+    return *this;
+  }
+
+  // Move construction and assignment.
+  StatusOr(StatusOr &&other) noexcept
+      : status_(std::move(other.status_)), has_value_(other.has_value_) {
+    if (has_value_) {
+      new (&value_) T(std::move(other.value_));
+    }
+  }
+  StatusOr &operator=(StatusOr &&other) noexcept {
+    if (this == &other) {
+      return *this;
+    }
+    Clear();
+    status_ = std::move(other.status_);
+    has_value_ = other.has_value_;
+    if (has_value_) {
+      new (&value_) T(std::move(other.value_));
+    }
+    return *this;
+  }
+
+  // Allow implicit conversion from `StatusOr<U>` to `StatusOr<T>` whenever `U`
+  // is convertible to `T` (e.g. `StatusOr<Derived>` to `StatusOr<Base>`).
+  template <typename U,
+            typename = std::enable_if_t<std::is_convertible<U, T>::value &&
+                                        !std::is_same<U, T>::value>>
+  StatusOr(const StatusOr<U> &other)  // NOLINT(runtime/explicit)
+      : status_(other.status()), has_value_(other.ok()) {
+    if (has_value_) {
+      new (&value_) T(*other);
+    }
+  }
+
+  template <typename U,
+            typename = std::enable_if_t<std::is_convertible<U, T>::value &&
+                                        !std::is_same<U, T>::value>>
+  StatusOr(StatusOr<U> &&other)  // NOLINT(runtime/explicit)
+      : status_(other.status()), has_value_(other.ok()) {
+    if (has_value_) {
+      new (&value_) T(*std::move(other));
+    }
+  }
+
+  ~StatusOr() { Clear(); }
+
+  // Returns true if this instance holds a value.
+  bool ok() const { return has_value_; }
+  explicit operator bool() const { return has_value_; }
+
+  // Returns the contained status. If a value is held, this is OK.
+  const Status &status() const { return status_; }
+
+  // Returns the status code.
+  StatusCode code() const { return status_.code(); }
+
+  // Returns a reference to the contained value. Fatal if no value is held.
+  const T &value() const & {
+    RAY_CHECK(has_value_) << "StatusOr has no value: " << status_.ToString();
+    return value_;
+  }
+  T &value() & {
+    RAY_CHECK(has_value_) << "StatusOr has no value: " << status_.ToString();
+    return value_;
+  }
+  const T &&value() const && {
+    RAY_CHECK(has_value_) << "StatusOr has no value: " << status_.ToString();
+    return std::move(value_);
+  }
+  T &&value() && {
+    RAY_CHECK(has_value_) << "StatusOr has no value: " << status_.ToString();
+    return std::move(value_);
+  }
+
+  // Dereference operators. Behavior is undefined if no value is held.
+  const T &operator*() const & { return value_; }
+  T &operator*() & { return value_; }
+  const T &&operator*() const && { return std::move(value_); }
+  T &&operator*() && { return std::move(value_); }
+
+  const T *operator->() const { return &value_; }
+  T *operator->() { return &value_; }
+
+  // Returns the contained value if present, otherwise `default_val`.
+  template <typename U>
+  T value_or(U &&default_val) const & {
+    if (has_value_) {
+      return value_;
+    }
+    return static_cast<T>(std::forward<U>(default_val));
+  }
+  template <typename U>
+  T value_or(U &&default_val) && {
+    if (has_value_) {
+      return std::move(value_);
+    }
+    return static_cast<T>(std::forward<U>(default_val));
+  }
+
+  // Returns the contained value if present, otherwise a default-constructed T.
+  T value_or_default() const & {
+    if (has_value_) {
+      return value_;
+    }
+    return T{};
+  }
+  T value_or_default() && {
+    if (has_value_) {
+      return std::move(value_);
+    }
+    return T{};
+  }
+
+  // Applies `f` to the contained value and returns the result. If no value is
+  // held, forwards the error status.
+  template <typename F>
+  auto and_then(F &&f) const & {
+    using Result = std::invoke_result_t<F, const T &>;
+    if (has_value_) {
+      return std::forward<F>(f)(value_);
+    }
+    return Result(status_);
+  }
+  template <typename F>
+  auto and_then(F &&f) && {
+    using Result = std::invoke_result_t<F, T &&>;
+    if (has_value_) {
+      return std::forward<F>(f)(std::move(value_));
+    }
+    return Result(std::move(status_));
+  }
+
+  // If a value is held, returns it. Otherwise applies `f` to the status to
+  // recover.
+  template <typename F>
+  auto or_else(F &&f) const & {
+    using Result = std::invoke_result_t<F, const Status &>;
+    if (has_value_) {
+      return Result(value_);
+    }
+    return std::forward<F>(f)(status_);
+  }
+  template <typename F>
+  auto or_else(F &&f) && {
+    using Result = std::invoke_result_t<F, Status &&>;
+    if (has_value_) {
+      return Result(std::move(value_));
+    }
+    return std::forward<F>(f)(std::move(status_));
+  }
+
+  // Swaps the contents of this with `other`.
+  void swap(StatusOr &other) {
+    if (this == &other) {
+      return;
+    }
+    if (has_value_ && other.has_value_) {
+      using std::swap;
+      swap(value_, other.value_);
+      swap(status_, other.status_);
+    } else if (has_value_ && !other.has_value_) {
+      Status other_status = std::move(other.status_);
+      other.status_ = std::move(status_);
+      new (&other.value_) T(std::move(value_));
+      Clear();
+      status_ = std::move(other_status);
+      other.has_value_ = true;
+    } else if (!has_value_ && other.has_value_) {
+      other.swap(*this);
+      return;
+    } else {
+      using std::swap;
+      swap(status_, other.status_);
+    }
+  }
+
+ private:
+  template <typename U>
+  friend class StatusOr;
+
+  // Destroys the contained value (if any) and resets `has_value_`.
+  void Clear() {
+    if (has_value_) {
+      value_.~T();
+      has_value_ = false;
+    }
+  }
+
+  Status status_;
+  union {
+    T value_;
+  };
+  bool has_value_;
+};
+
+template <typename T>
+bool operator==(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
+  if (lhs.ok() != rhs.ok()) {
+    return false;
+  }
+  if (lhs.ok()) {
+    return *lhs == *rhs;
+  }
+  return lhs.code() == rhs.code();
+}
+
+template <typename T>
+bool operator!=(const StatusOr<T> &lhs, const StatusOr<T> &rhs) {
+  return !(lhs == rhs);
+}
+
+template <typename T>
+void swap(StatusOr<T> &lhs, StatusOr<T> &rhs) {
+  lhs.swap(rhs);
+}
+
+}  // namespace ray
